package ae.wasm;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class LebTest {
    private static Reader rd(int... b) {
        byte[] x = Bin.bytes(b);
        return new Reader(x, 0, x.length);
    }

    @Test
    void unsignedLiterals() {
        assertEquals(624485L, rd(0xE5, 0x8E, 0x26).leb(32, false)); // Wikipedia example
        assertEquals(0L, rd(0x00).leb(32, false));
        assertEquals(127L, rd(0x7F).leb(32, false));
        assertEquals(128L, rd(0x80, 0x01).leb(32, false));
        assertEquals(4294967295L, rd(0xFF, 0xFF, 0xFF, 0xFF, 0x0F).leb(32, false));
    }

    @Test
    void signedLiterals() {
        assertEquals(-123456L, rd(0xC0, 0xBB, 0x78).leb(32, true)); // Wikipedia example
        assertEquals(-1L, rd(0x7F).leb(32, true));
        assertEquals(63L, rd(0x3F).leb(32, true));
        assertEquals(-64L, rd(0x40).leb(32, true));
        assertEquals(64L, rd(0xC0, 0x00).leb(32, true));
        assertEquals(Integer.MIN_VALUE, rd(0x80, 0x80, 0x80, 0x80, 0x78).leb(32, true));
        assertEquals(Integer.MAX_VALUE, rd(0xFF, 0xFF, 0xFF, 0xFF, 0x07).leb(32, true));
        assertEquals(Long.MIN_VALUE,
                rd(0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x7F).leb(64, true));
        assertEquals(Long.MAX_VALUE,
                rd(0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x00).leb(64, true));
    }

    @Test
    void redundantPaddingWithinByteLimitIsAccepted() {
        // 0 encoded in 5 bytes is legal for u32 (the limit is the byte count, not minimality)
        assertEquals(0L, rd(0x80, 0x80, 0x80, 0x80, 0x00).leb(32, false));
        assertEquals(-1L, rd(0xFF, 0xFF, 0xFF, 0xFF, 0x7F).leb(32, true));
    }

    @Test
    void tooLongOrBadUnusedBitsRejected() {
        // sixth byte
        assertThrows(ModuleException.class, () -> rd(0x80, 0x80, 0x80, 0x80, 0x80, 0x00).leb(32, false));
        // fifth byte has bit 4 set (value >= 2^32)
        assertThrows(ModuleException.class, () -> rd(0xFF, 0xFF, 0xFF, 0xFF, 0x10).leb(32, false));
        // signed: fifth byte 0x70 has unused bits set but sign bit (bit 3) clear
        assertThrows(ModuleException.class, () -> rd(0x80, 0x80, 0x80, 0x80, 0x70).leb(32, true));
        // signed: sign bit set but unused bits not all ones
        assertThrows(ModuleException.class, () -> rd(0x80, 0x80, 0x80, 0x80, 0x48).leb(32, true));
        // s64: last byte must be 0x00 or 0x7F
        assertThrows(ModuleException.class,
                () -> rd(0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x01).leb(64, true));
        // continuation bit still set on the last permitted byte
        assertThrows(ModuleException.class, () -> rd(0xFF, 0xFF, 0xFF, 0xFF, 0x8F, 0x00).leb(32, false));
    }

    @Test
    void truncatedReportsOffset() {
        ModuleException e = assertThrows(ModuleException.class, () -> rd(0x80, 0x80).leb(32, false));
        assertEquals(ModuleException.Kind.MALFORMED, e.kind());
        assertTrue(e.getMessage().startsWith("malformed at offset 2: "), e.getMessage());
    }

    @Test
    void roundTripWithTestEncoder() {
        long[] vals = {0, 1, 63, 64, 127, 128, 8191, 8192, 1L << 31, (1L << 32) - 1};
        for (long v : vals) {
            byte[] enc = Bin.u(v);
            assertEquals(v, new Reader(enc, 0, enc.length).leb(32, false), "u " + v);
        }
        long[] svals = {0, 1, -1, 63, 64, -64, -65, Integer.MIN_VALUE, Integer.MAX_VALUE, 123456789, -987654321};
        for (long v : svals) {
            byte[] enc = Bin.s(v);
            assertEquals(v, new Reader(enc, 0, enc.length).leb(32, true), "s " + v);
        }
        long[] lvals = {Long.MIN_VALUE, Long.MAX_VALUE, -1L << 40, 1L << 40, 0x123456789ABCDEFL};
        for (long v : lvals) {
            byte[] enc = Bin.s(v);
            assertEquals(v, new Reader(enc, 0, enc.length).leb(64, true), "l " + v);
        }
    }

    @Test
    void s33BlockTypeBytes() {
        assertEquals(-64L, rd(0x40).leb(33, true));
        assertEquals(-1L, rd(0x7F).leb(33, true));
        assertEquals(-2L, rd(0x7E).leb(33, true));
        // s33 spans -2^32 .. 2^32-1: the 5th byte carries bits 28..32 with bit 32 (byte bit 4) as the sign
        assertEquals(-(1L << 32), rd(0x80, 0x80, 0x80, 0x80, 0x70).leb(33, true));
        assertEquals(0xF0000000L, rd(0x80, 0x80, 0x80, 0x80, 0x0F).leb(33, true));
        // 0x10 would mean sign bit set with bits 5-6 clear: not a sign extension
        assertThrows(ModuleException.class, () -> rd(0x80, 0x80, 0x80, 0x80, 0x10).leb(33, true));
    }

    @Test
    void vecCountIsCheckedAgainstRemainingBytesBeforeAllocation() {
        Reader r = rd(0xFF, 0xFF, 0xFF, 0xFF, 0x0F, 0x01);
        ModuleException e = assertThrows(ModuleException.class, r::vecCount);
        assertTrue(e.getMessage().contains("count exceeds remaining"), e.getMessage());
        Reader ok = rd(0x02, 0xAA, 0xBB);
        assertEquals(2, ok.vecCount());
        // exactly one more than the bytes that remain after the count byte
        assertThrows(ModuleException.class, () -> rd(0x03, 0xAA, 0xBB).vecCount());
        assertEquals(0, rd(0x00).vecCount());
    }
}

tests.src/test/java/ae/wasm/ParserTest.java:
package ae.wasm;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.fail;

import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

class ParserTest {
    private static final byte[] HEADER = Bin.bytes(0x00, 0x61, 0x73, 0x6D, 0x01, 0x00, 0x00, 0x00);

    private static ModuleException malformed(byte[] image) {
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(image));
        assertEquals(ModuleException.Kind.MALFORMED, e.kind(), e.getMessage());
        assertTrue(e.getMessage().startsWith("malformed at offset "), e.getMessage());
        return e;
    }

    private static ModuleException invalid(byte[] image) {
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(image));
        assertEquals(ModuleException.Kind.INVALID, e.kind(), e.getMessage());
        return e;
    }

    private static Bin.M richModule() {
        Bin.M m = new Bin.M();
        int t = m.type("ii:i");
        int t0 = m.type(":");
        int g = m.global('i', true, 5);
        m.mem(1, 2);
        int add = m.func(t, "l", Bin.c().get(0).get(1).b(0x6A));
        int st = m.func(t0, "", Bin.c().i32(7).gset(g));
        m.exportFunc("add", add);
        m.export("mem", 2, 0);
        m.export("g", 3, g);
        m.start(st);
        m.data(8, new byte[] {1, 2, 3});
        m.custom = Bin.cat(Bin.u(4), "note".getBytes(StandardCharsets.UTF_8), Bin.bytes(9, 9, 9));
        return m;
    }

    @Test
    void emptyModuleParses() {
        Module m = ModuleParser.parse(HEADER);
        assertEquals(0, m.functionCount());
    }

    @Test
    void headerErrors() {
        malformed(new byte[0]);
        malformed(Bin.bytes(0x00, 0x61, 0x73));
        malformed(Bin.bytes(0x00, 0x61, 0x73, 0x6E, 0x01, 0x00, 0x00, 0x00));
        ModuleException v = malformed(Bin.bytes(0x00, 0x61, 0x73, 0x6D, 0x02, 0x00, 0x00, 0x00));
        assertTrue(v.getMessage().contains("unknown binary version"), v.getMessage());
        ModuleException magic = malformed(Bin.bytes(1, 2, 3, 4, 1, 0, 0, 0));
        assertTrue(magic.getMessage().contains("magic"), magic.getMessage());
    }

    @Test
    void richModuleParsesAndRuns() {
        Module m = ModuleParser.parse(richModule().build());
        assertEquals(2, m.functionCount());
        Instance inst = Instance.instantiate(m);
        assertEquals(7L, inst.global("g")); // start function ran
        assertEquals(1, inst.memoryPages());
        assertEquals(5L, inst.invoke("add", 2, 3)[0]);
    }

    @Test
    void sectionOrderAndDuplicates() {
        Bin.M m = richModule();
        byte[] image = m.build();
        // swap: append a second type section after everything -> id 1 after id 11
        byte[] extra = Bin.cat(image, Bin.bytes(1, 1, 0));
        ModuleException e = malformed(extra);
        assertTrue(e.getMessage().contains("unexpected section order"), e.getMessage());
        // duplicate: two memory sections
        byte[] one = Bin.cat(HEADER, Bin.bytes(5, 3, 1, 0, 1));
        ModuleParser.parse(one); // control: a single memory section is fine
        byte[] dup = Bin.cat(one, Bin.bytes(5, 3, 1, 0, 1));
        ModuleException d = malformed(dup);
        assertTrue(d.getMessage().contains("unexpected section order"), d.getMessage());
    }

    @Test
    void customSectionsAnywhereAreSkipped() {
        byte[] custom = Bin.cat(Bin.bytes(0, 5), Bin.bytes(4), "abcd".getBytes(StandardCharsets.UTF_8));
        Bin.M m = new Bin.M();
        int t = m.type(":i");
        int f = m.func(t, "", Bin.c().i32(42));
        m.exportFunc("f", f);
        byte[] img = m.build();
        byte[] withTrailingCustom = Bin.cat(img, custom);
        byte[] withLeadingCustom = Bin.cat(HEADER, custom, java.util.Arrays.copyOfRange(img, 8, img.length));
        assertEquals(42L, Instance.instantiate(ModuleParser.parse(withTrailingCustom)).invoke("f")[0]);
        assertEquals(42L, Instance.instantiate(ModuleParser.parse(withLeadingCustom)).invoke("f")[0]);
    }

    @Test
    void customSectionNameMustFitAndBeUtf8() {
        // name length 9 but section holds only 3 bytes
        malformed(Bin.cat(HEADER, Bin.bytes(0, 3, 9, 0x61, 0x62)));
        // invalid UTF-8 name (0xC0 0x80 is an overlong NUL)
        malformed(Bin.cat(HEADER, Bin.bytes(0, 3, 2, 0xC0, 0x80)));
    }

    @Test
    void sectionSizeMismatchAndOverrun() {
        // type section declaring size 5 but its vec(0) uses only 1 byte
        ModuleException e = malformed(Bin.cat(HEADER, Bin.bytes(1, 5, 0, 0, 0, 0, 0)));
        assertTrue(e.getMessage().contains("section size mismatch"), e.getMessage());
        // size larger than the rest of the file
        ModuleException e2 = malformed(Bin.cat(HEADER, Bin.bytes(1, 100, 0)));
        assertTrue(e2.getMessage().contains("section size"), e2.getMessage());
    }

    @Test
    void unknownSectionIdAndUnsupportedSections() {
        malformed(Bin.cat(HEADER, Bin.bytes(13, 0)));
        for (int id : new int[] {2, 4, 9, 12}) {
            ModuleException e = invalid(Bin.cat(HEADER, Bin.bytes(id, 1, 0)));
            assertTrue(e.getMessage().contains("unsupported section"), id + " " + e.getMessage());
        }
    }

    @Test
    void hostileCountsDoNotAllocate() {
        // type vec claims 2^32-1 entries with 1 byte left
        ModuleException e = malformed(Bin.cat(HEADER, Bin.bytes(1, 6, 0xFF, 0xFF, 0xFF, 0xFF, 0x0F, 0)));
        assertTrue(e.getMessage().contains("count exceeds remaining"), e.getMessage());
        // function body with locals group count 2^32-1
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.funcRaw(t, Bin.cat(Bin.u(1), Bin.u(0xFFFFFFFFL), Bin.bytes(0x7F), Bin.bytes(0x0B)));
        invalid(m.build());
    }

    @Test
    void tooManyLocalsIsInvalid() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.funcRaw(t, Bin.cat(Bin.u(1), Bin.u(50001), Bin.bytes(0x7F), Bin.bytes(0x0B)));
        assertTrue(invalid(m.build()).getMessage().contains("too many locals"));
        Bin.M ok = new Bin.M();
        int t2 = ok.type(":");
        ok.funcRaw(t2, Bin.cat(Bin.u(1), Bin.u(50000), Bin.bytes(0x7F), Bin.bytes(0x0B)));
        ModuleParser.parse(ok.build());
    }

    @Test
    void functionAndCodeCountsMustAgree() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.func(t, "", Bin.c());
        byte[] img = m.build();
        // drop the code section (last section) entirely
        byte[] noCode = java.util.Arrays.copyOf(img, m.sectionEnds.get(m.sectionEnds.size() - 2));
        ModuleException e = malformed(noCode);
        assertTrue(e.getMessage().contains("inconsistent lengths"), e.getMessage());
    }

    @Test
    void functionBodySizeMustMatchExactly() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        // entry = locals(0) + end + one stray nop after the end
        m.funcRaw(t, Bin.bytes(0, 0x0B, 0x01));
        ModuleException e = malformed(m.build());
        assertTrue(e.getMessage().contains("operators remaining after end of function"), e.getMessage());
        Bin.M m2 = new Bin.M();
        int t2 = m2.type(":");
        m2.funcRaw(t2, Bin.bytes(0, 0x01)); // no end
        malformed(m2.build());
    }

    @Test
    void illegalOpcodeAndValueTypeAreMalformed() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.func(t, "", Bin.c().b(0xFF));
        assertTrue(malformed(m.build()).getMessage().contains("illegal opcode 0xff"));
        Bin.M m2 = new Bin.M();
        m2.types.add(Bin.bytes(0x60, 1, 0x7D, 0)); // f32 param
        assertTrue(malformed(m2.build()).getMessage().contains("unsupported value type"));
        Bin.M m3 = new Bin.M();
        m3.types.add(Bin.bytes(0x61, 0, 0)); // wrong form byte
        malformed(m3.build());
    }

    @Test
    void memoryLimitsValidation() {
        Bin.M m = new Bin.M();
        m.memory = Bin.bytes(1, 0, 0x80, 0x80, 0x04); // min 65536 pages: allowed
        ModuleParser.parse(m.build());
        m.memory = Bin.bytes(1, 0, 0x81, 0x80, 0x04); // 65537
        assertTrue(invalid(m.build()).getMessage().contains("at most 65536 pages"));
        m.memory = Bin.bytes(1, 1, 3, 2); // min 3 > max 2
        assertTrue(invalid(m.build()).getMessage().contains("minimum must not be greater than maximum"));
        m.memory = Bin.bytes(1, 2, 3); // bad flag
        malformed(m.build());
        byte[] two = Bin.cat(HEADER, Bin.bytes(5, 5, 2, 0, 1, 0, 1));
        assertTrue(invalid(two).getMessage().contains("multiple memories"));
    }

    @Test
    void exportValidation() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        int f = m.func(t, "", Bin.c());
        m.exportFunc("a", f).exportFunc("a", f);
        assertTrue(invalid(m.build()).getMessage().contains("duplicate export name"));
        Bin.M m2 = new Bin.M();
        m2.type(":");
        m2.func(0, "", Bin.c());
        m2.exportFunc("x", 5);
        assertTrue(invalid(m2.build()).getMessage().contains("unknown function"));
        Bin.M m3 = new Bin.M();
        m3.export("m", 2, 0);
        assertTrue(invalid(m3.build()).getMessage().contains("unknown memory"));
        Bin.M m4 = new Bin.M();
        m4.export("g", 3, 0);
        assertTrue(invalid(m4.build()).getMessage().contains("unknown global"));
        Bin.M m5 = new Bin.M();
        m5.exports.add(Bin.cat(Bin.u(1), Bin.bytes('t', 1, 0))); // table export
        assertTrue(invalid(m5.build()).getMessage().contains("unsupported export kind"));
        Bin.M m6 = new Bin.M();
        m6.exports.add(Bin.cat(Bin.u(2), Bin.bytes(0xC3, 0x28, 0, 0))); // invalid UTF-8 name
        malformed(m6.build());
    }

    @Test
    void startFunctionMustBeUnitTyped() {
        Bin.M m = new Bin.M();
        int t = m.type(":i");
        int f = m.func(t, "", Bin.c().i32(1));
        m.start(f);
        assertTrue(invalid(m.build()).getMessage().contains("start function must have type [] -> []"));
        Bin.M m2 = new Bin.M();
        m2.start(0);
        assertTrue(invalid(m2.build()).getMessage().contains("unknown function"));
    }

    @Test
    void globalInitializers() {
        Bin.M m = new Bin.M();
        m.globals.add(Bin.cat(Bin.bytes(0x7F, 0, 0x42), Bin.s(1), Bin.bytes(0x0B))); // i32 global with i64.const
        assertTrue(invalid(m.build()).getMessage().contains("constant expression type mismatch"));
        Bin.M m2 = new Bin.M();
        m2.globals.add(Bin.cat(Bin.bytes(0x7F, 0, 0x6A, 0x0B))); // i32.add in const expr
        assertTrue(invalid(m2.build()).getMessage().contains("unsupported constant expression"));
        Bin.M m3 = new Bin.M();
        m3.globals.add(Bin.cat(Bin.bytes(0x7F, 2, 0x41, 0, 0x0B))); // mutability byte 2
        malformed(m3.build());
        Bin.M m4 = new Bin.M();
        m4.globals.add(Bin.cat(Bin.bytes(0x7F, 0, 0x41, 0))); // missing end
        malformed(m4.build());
        Bin.M m5 = new Bin.M();
        m5.globals.add(Bin.cat(Bin.bytes(0x7F, 0, 0x41, 0, 0x0B, 0x0B))); // two ends: size mismatch
        malformed(m5.build());
    }

    @Test
    void dataSegmentsNeedMemoryAndFitAtLinkTime() {
        Bin.M m = new Bin.M();
        m.data(0, new byte[] {1});
        assertTrue(invalid(m.build()).getMessage().contains("unknown memory"));
        Bin.M m2 = new Bin.M();
        m2.mem(1, -1);
        m2.data(65535, new byte[] {1, 2});
        Module parsed = ModuleParser.parse(m2.build());
        ModuleException e = assertThrows(ModuleException.class, () -> Instance.instantiate(parsed));
        assertEquals(ModuleException.Kind.LINK, e.kind());
        assertTrue(e.getMessage().contains("data segment does not fit"), e.getMessage());
        Bin.M m3 = new Bin.M();
        m3.mem(1, -1);
        m3.data(65534, new byte[] {1, 2});
        Instance ok = Instance.instantiate(ModuleParser.parse(m3.build()));
        assertEquals(2, ok.readMemory(65534, 2)[1]);
        // bad segment flag
        Bin.M m4 = new Bin.M();
        m4.mem(1, -1);
        m4.data.add(Bin.bytes(1, 0));
        malformed(m4.build());
    }

    @Test
    void everyTruncationIsRejectedUnlessItIsASectionBoundary() {
        Bin.M m = richModule();
        byte[] img = m.build();
        for (int len = 0; len < img.length; len++) {
            byte[] prefix = java.util.Arrays.copyOf(img, len);
            boolean boundary = m.sectionEnds.contains(len);
            try {
                ModuleParser.parse(prefix);
                if (!boundary) {
                    fail("prefix of length " + len + " of " + img.length + " parsed");
                }
            } catch (ModuleException e) {
                if (!boundary) {
                    assertEquals(ModuleException.Kind.MALFORMED, e.kind(), "len " + len + ": " + e.getMessage());
                }
            }
        }
    }

    @Test
    void everyByteFlipEitherParsesOrThrowsModuleExceptionAndSurvivorsRunSafely() {
        byte[] img = richModule().build();
        int parsedOk = 0;
        int rejected = 0;
        for (int i = 0; i < img.length; i++) {
            for (int mask : new int[] {0x01, 0x80, 0xFF, 0x40}) {
                byte[] b = img.clone();
                b[i] ^= (byte) mask;
                Module m;
                try {
                    m = ModuleParser.parse(b);
                } catch (ModuleException e) {
                    rejected++;
                    continue;
                }
                parsedOk++;
                try {
                    Instance inst = Instance.instantiate(m, 10_000);
                    for (String name : m.exportedFunctions()) {
                        try {
                            long[] args = new long[m.exportArity(name)];
                            inst.invoke(name, args);
                        } catch (Trap expected) {
                            // traps are legitimate outcomes of mutated programs
                        }
                    }
                } catch (ModuleException | Trap expected) {
                    // link errors (e.g. data segment moved out of bounds) and start-function traps are fine
                }
            }
        }
        assertTrue(rejected > 100, "rejected " + rejected);
        assertTrue(parsedOk > 20, "parsedOk " + parsedOk);
    }

    @Test
    void memoryLimitBoundaries() {
        Bin.M m = new Bin.M();
        m.memory = Bin.bytes(1, 1, 1, 0x80, 0x80, 0x04); // min 1, max 65536: allowed
        ModuleParser.parse(m.build());
        m.memory = Bin.bytes(1, 1, 1, 0x81, 0x80, 0x04); // max 65537
        assertTrue(invalid(m.build()).getMessage().contains("at most 65536 pages"));
        m.memory = Bin.bytes(1, 1, 2, 2); // min == max is legal
        ModuleParser.parse(m.build());
    }

    @Test
    void exportIndexBoundaries() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        int f = m.func(t, "", Bin.c());
        m.exportFunc("ok", f);
        ModuleParser.parse(m.build()); // control: the last valid index
        m.exportFunc("bad", f + 1); // one past the last function
        assertTrue(invalid(m.build()).getMessage().contains("unknown function"));
        Bin.M g = new Bin.M();
        g.mem(1, -1);
        g.export("m", 2, 0);
        ModuleParser.parse(g.build());
        g.export("m2", 2, 1); // only memory index 0 exists
        assertTrue(invalid(g.build()).getMessage().contains("unknown memory"));
        Bin.M gl = new Bin.M();
        int gi = gl.global('i', false, 1);
        gl.export("g", 3, gi);
        ModuleParser.parse(gl.build());
        gl.export("g2", 3, gi + 1);
        assertTrue(invalid(gl.build()).getMessage().contains("unknown global"));
    }

    @Test
    void startFunctionWithParametersIsInvalid() {
        Bin.M m = new Bin.M();
        int t = m.type("i:");
        int f = m.func(t, "", Bin.c());
        m.start(f);
        assertTrue(invalid(m.build()).getMessage().contains("start function must have type [] -> []"));
        Bin.M ok = new Bin.M();
        int t0 = ok.type(":");
        ok.start(ok.func(t0, "", Bin.c()));
        ModuleParser.parse(ok.build());
    }

    @Test
    void constantExpressionMustEndWithEndMarker() {
        Bin.M m = new Bin.M();
        m.globals.add(Bin.bytes(0x7F, 0, 0x41, 0, 0x0C)); // ends with br instead of end
        ModuleException e = malformed(m.build());
        assertTrue(e.getMessage().contains("missing its end marker"), e.getMessage());
        Bin.M ok = new Bin.M();
        ok.globals.add(Bin.bytes(0x7F, 0, 0x41, 0, 0x0B));
        ModuleParser.parse(ok.build());
    }

    @Test
    void multipleMemoryDeclarationsFailBeforeSizeChecks() {
        // count 2 with two well-formed entries: must be INVALID "multiple memories", not a size mismatch
        byte[] two = Bin.cat(HEADER, Bin.bytes(5, 5, 2, 0, 1, 0, 1));
        assertTrue(invalid(two).getMessage().contains("multiple memories"));
    }

    @Test
    void functionBodySizeBeyondTheCodeSectionIsMalformed() {
        // two sections: code (body claims one byte more than the section holds) followed by data
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.funcTypes.add(t);
        m.mem(1, -1);
        m.codes.add(Bin.bytes(0, 0x0B));
        m.data(0, new byte[] {1});
        byte[] ok = m.build();
        ModuleParser.parse(ok); // control
        // locate the code section: id 0x0A, then size, count 1, body size 2. Bump the body size to 3.
        int at = -1;
        for (int i = 8; i + 4 < ok.length; i++) {
            if (ok[i] == 0x0A && ok[i + 1] == 4 && ok[i + 2] == 1 && ok[i + 3] == 2) {
                at = i + 3;
                break;
            }
        }
        assertTrue(at > 0, "code section not found");
        byte[] bad = ok.clone();
        bad[at] = 3;
        ModuleException e = malformed(bad);
        assertTrue(e.getMessage().contains("function body size exceeds remaining bytes"), e.getMessage());
    }
}

tests.src/test/java/ae/wasm/ValidatorTest.java:
package ae.wasm;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import java.util.stream.Stream;

class ValidatorTest {
    /** A one-function module with signature {@code sig}, locals {@code locals}, one memory and one i32 mutable + one i64 immutable global. */
    private static byte[] module(String sig, String locals, Bin.C body) {
        Bin.M m = new Bin.M();
        int t = m.type(sig);
        m.type("i:i"); // type 1 used by call tests
        m.mem(1, -1);
        m.global('i', true, 0); // global 0: mutable i32
        m.global('l', false, 0); // global 1: immutable i64
        m.func(t, locals, body);
        return m.build();
    }

    private static void ok(String sig, String locals, Bin.C body) {
        ModuleParser.parse(module(sig, locals, body));
    }

    private static void bad(String sig, String locals, Bin.C body, String message) {
        ModuleException e = assertThrows(ModuleException.class,
                () -> ModuleParser.parse(module(sig, locals, body)), message);
        assertEquals(ModuleException.Kind.INVALID, e.kind(), e.getMessage());
        assertTrue(e.getMessage().contains(message), "expected '" + message + "' in: " + e.getMessage());
    }

    static Stream<Arguments> invalidBodies() {
        return Stream.of(
            // [sig, locals, body, expected message]
            Arguments.of(":i", "", Bin.c(), "stack underflow"),                             // result missing
            Arguments.of(":i", "", Bin.c().i64(1), "type mismatch"),                        // wrong result type
            Arguments.of(":", "", Bin.c().i32(1), "stack height mismatch"),                 // leftover value
            Arguments.of(":i", "", Bin.c().i32(1).i32(2), "stack height mismatch"),         // extra value
            Arguments.of(":i", "", Bin.c().i32(1).b(0x6A), "stack underflow"),              // i32.add with 1 operand
            Arguments.of(":", "", Bin.c().b(0x6A), "stack underflow"),
            Arguments.of(":i", "", Bin.c().i32(1).i64(2).b(0x6A), "type mismatch"),         // i32.add (i32, i64)
            Arguments.of(":i", "", Bin.c().i64(1).i32(2).b(0x6A), "type mismatch"),
            Arguments.of(":i", "", Bin.c().i64(1).i64(2).b(0x6A), "type mismatch"),
            Arguments.of(":l", "", Bin.c().i32(1).i32(2).b(0x7C), "type mismatch"),         // i64.add on i32s
            Arguments.of(":i", "", Bin.c().i64(1).b(0xA7).b(0xA7), "type mismatch"),        // wrap of an i32
            Arguments.of(":l", "", Bin.c().i64(1).b(0xAC), "type mismatch"),                // extend_s of an i64
            Arguments.of(":i", "", Bin.c().get(0), "unknown local"),
            Arguments.of("i:i", "", Bin.c().get(1), "unknown local"),
            Arguments.of("i:", "", Bin.c().i32(1).set(1), "unknown local"),
            Arguments.of("i:", "", Bin.c().i64(1).set(0), "type mismatch"),                 // set i32 local with i64
            Arguments.of("i:i", "", Bin.c().i64(1).tee(0), "type mismatch"),
            Arguments.of(":i", "", Bin.c().gget(9), "unknown global"),
            Arguments.of(":i", "", Bin.c().gget(2), "unknown global"),                       // module() declares globals 0 and 1
            Arguments.of(":", "", Bin.c().call(1), "unknown function"),                      // the module has exactly one function
            Arguments.of(":", "", Bin.c().i32(1).gset(1), "immutable global"),              // global 1 is i64 immutable
            Arguments.of(":", "", Bin.c().i64(1).gset(0), "type mismatch"),                 // global 0 is i32
            Arguments.of(":", "", Bin.c().i32(1).gset(7), "unknown global"),
            Arguments.of(":", "", Bin.c().call(5), "unknown function"),
            Arguments.of(":", "", Bin.c().br(1), "unknown label"),                          // only the function label exists
            Arguments.of(":", "", Bin.c().b(0x02, 0x40).br(2).end(), "unknown label"),
            Arguments.of(":", "", Bin.c().i32(0).brIf(1), "unknown label"),
            Arguments.of(":i", "", Bin.c().b(0x02, 0x7F).end(), "stack underflow"),          // block (result i32) empty
            Arguments.of(":", "", Bin.c().b(0x02, 0x40).i32(1).end(), "stack height mismatch"),
            Arguments.of(":i", "", Bin.c().i32(1).b(0x04, 0x7F).i32(1).end(), "if without else cannot have a result"),
            Arguments.of(":", "", Bin.c().b(0x04, 0x40).end(), "stack underflow"),          // if without condition
            Arguments.of(":", "", Bin.c().i64(1).b(0x04, 0x40).end(), "type mismatch"),     // i64 condition
            Arguments.of(":", "", Bin.c().b(0x05), "else without if"),
            Arguments.of(":", "", Bin.c().b(0x02, 0x40).b(0x05).end(), "else without if"),
            Arguments.of(":", "", Bin.c().i32(1).b(0x04, 0x40).b(0x05).b(0x05).end(), "else without if"),
            Arguments.of(":i", "", Bin.c().i32(1).b(0x04, 0x7F).i32(1).b(0x05).i64(2).end(), "type mismatch"),
            Arguments.of(":", "", Bin.c().b(0x1A), "stack underflow"),                      // drop on empty
            Arguments.of(":i", "", Bin.c().i32(1).i64(2).i32(1).b(0x1B), "type mismatch"),  // select with mixed operand types
            Arguments.of(":i", "", Bin.c().i32(1).i32(2).i64(1).b(0x1B), "type mismatch"),  // select condition must be i32
            Arguments.of(":", "", Bin.c().i32(0).i32(0).b(0x1B), "stack underflow"),
            // memory
            Arguments.of(":i", "", Bin.c().i32(0).mem(0x28, 3, 0), "alignment must not be larger than natural"),
            Arguments.of(":l", "", Bin.c().i32(0).mem(0x29, 4, 0), "alignment must not be larger than natural"),
            Arguments.of(":i", "", Bin.c().i32(0).mem(0x2C, 1, 0), "alignment must not be larger than natural"),
            Arguments.of(":i", "", Bin.c().i32(0).mem(0x2E, 2, 0), "alignment must not be larger than natural"),
            Arguments.of(":", "", Bin.c().i32(0).i32(0).mem(0x3A, 1, 0), "alignment must not be larger than natural"),
            Arguments.of(":", "", Bin.c().i32(0).i32(0).mem(0x3B, 2, 0), "alignment must not be larger than natural"),
            Arguments.of(":", "", Bin.c().i32(0).i64(0).mem(0x36, 2, 0), "type mismatch"),  // i32.store of i64
            Arguments.of(":", "", Bin.c().i64(0).i64(0).mem(0x37, 3, 0), "type mismatch"),  // i64.store with i64 address
            Arguments.of(":i", "", Bin.c().i64(0).mem(0x28, 2, 0), "type mismatch")         // i64 address
        );
    }

    @ParameterizedTest
    @MethodSource("invalidBodies")
    void rejects(String sig, String locals, Bin.C body, String message) {
        bad(sig, locals, body, message);
    }

    @Test
    void callChecksArgumentTypes() {
        // function 0 has type "ii:i"; module() adds only that one function, so build a two-function module
        Bin.M m = new Bin.M();
        int t = m.type("i:i");
        int callee = m.func(t, "", Bin.c().get(0));
        m.func(m.type(":i"), "", Bin.c().i64(1).call(callee));
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
        assertEquals(ModuleException.Kind.INVALID, e.kind());
        assertTrue(e.getMessage().contains("type mismatch"), e.getMessage());
        Bin.M ok = new Bin.M();
        int t2 = ok.type("i:i");
        int c2 = ok.func(t2, "", Bin.c().get(0));
        ok.func(ok.type(":i"), "", Bin.c().i32(1).call(c2));
        ModuleParser.parse(ok.build());
        Bin.M under = new Bin.M();
        int t3 = under.type("i:i");
        int c3 = under.func(t3, "", Bin.c().get(0));
        under.func(under.type(":i"), "", Bin.c().call(c3));
        assertTrue(assertThrows(ModuleException.class, () -> ModuleParser.parse(under.build()))
                .getMessage().contains("stack underflow"));
    }

    @Test
    void returnChecksItsOperand() {
        bad(":i", "", Bin.c().ret(), "stack underflow");                  // return with nothing for the i32 result
        bad(":i", "", Bin.c().i64(1).ret(), "type mismatch");            // wrong result type
        ok(":i", "", Bin.c().i32(1).ret());
        ok(":", "", Bin.c().ret());
    }

    @Test
    void elseArmStartsWithAFreshReachableStack() {
        // then-arm ends in unreachable code; the else arm must not inherit the polymorphic state
        bad(":i", "", Bin.c().i32(1).b(0x04, 0x7F).b(0x00).b(0x05).end(), "stack underflow");
        bad(":i", "", Bin.c().i32(1).b(0x04, 0x7F).i32(1).b(0x05).b(0x6A).end(), "stack underflow");
        ok(":i", "", Bin.c().i32(1).b(0x04, 0x7F).b(0x00).b(0x05).i32(2).end());
    }

    @Test
    void unknownTypeIndexInFunctionSection() {
        Bin.M m = new Bin.M();
        m.type(":");
        m.funcTypes.add(3);
        m.codes.add(Bin.bytes(0, 0x0B));
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
        assertEquals(ModuleException.Kind.INVALID, e.kind());
        assertTrue(e.getMessage().contains("unknown type"), e.getMessage());
        // one past the last type (there is exactly one type, index 0)
        Bin.M edge = new Bin.M();
        edge.type(":");
        edge.funcTypes.add(1);
        edge.codes.add(Bin.bytes(0, 0x0B));
        ModuleException e2 = assertThrows(ModuleException.class, () -> ModuleParser.parse(edge.build()));
        assertEquals(ModuleException.Kind.INVALID, e2.kind());
        assertTrue(e2.getMessage().contains("unknown type 1"), e2.getMessage());
    }

    @Test
    void multiValueResultsAreRejected() {
        Bin.M m = new Bin.M();
        int t = m.type(":ii");
        m.func(t, "", Bin.c().i32(1).i32(2));
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
        assertEquals(ModuleException.Kind.INVALID, e.kind());
        assertTrue(e.getMessage().contains("multiple results"), e.getMessage());
    }

    @Test
    void memoryInstructionsNeedAMemory() {
        for (Bin.C c : new Bin.C[] {Bin.c().i32(0).mem(0x28, 2, 0), Bin.c().b(0x3F, 0), Bin.c().i32(1).b(0x40, 0)}) {
            Bin.M m = new Bin.M();
            int t = m.type(":i");
            m.func(t, "", c);
            ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
            assertEquals(ModuleException.Kind.INVALID, e.kind());
            assertTrue(e.getMessage().contains("unknown memory"), e.getMessage());
        }
    }

    @Test
    void memoryOpsReservedByteMustBeZero() {
        Bin.M m = new Bin.M();
        int t = m.type(":i");
        m.mem(1, -1);
        m.func(t, "", Bin.c().b(0x3F, 1));
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
        assertEquals(ModuleException.Kind.MALFORMED, e.kind());
        assertTrue(e.getMessage().contains("zero byte expected"), e.getMessage());
    }

    @Test
    void unsupportedBlockTypeIsMalformed() {
        Bin.M m = new Bin.M();
        int t = m.type(":");
        m.func(t, "", Bin.c().b(0x02, 0x00).end()); // block with type index 0
        ModuleException e = assertThrows(ModuleException.class, () -> ModuleParser.parse(m.build()));
        assertEquals(ModuleException.Kind.MALFORMED, e.kind());
        assertTrue(e.getMessage().contains("unsupported block type"), e.getMessage());
    }

    // ---- valid programs relying on the stack-polymorphic rule ----

    @Test
    void transferDiscardsOperandsBelowTheTargetResult() {
        ok(":", "", Bin.c().i32(1).ret());               // return in a void function with a stray operand
        ok(":", "", Bin.c().i32(1).i64(2).br(0));        // br to the function label with stray operands
        ok(":", "", Bin.c().b(0x02, 0x40).i32(1).br(0).end());
        ok(":", "", Bin.c().i32(1).i32(0).brTable(0, 0));
    }

    @Test
    void polymorphicStackAfterUnconditionalTransfer() {
        ok(":i", "", Bin.c().b(0x00).b(0x6A));                       // unreachable; i32.add  -> [i32]
        ok(":i", "", Bin.c().b(0x00));                               // unreachable alone satisfies a result
        ok(":i", "", Bin.c().i32(1).ret().b(0x6A));                  // return; i32.add
        ok(":i", "", Bin.c().i32(1).br(0).b(0x6A, 0x6A));            // br 0; add; add
        ok(":l", "", Bin.c().b(0x00).b(0x7C));                       // i64.add under unreachable
        ok(":", "", Bin.c().b(0x00).b(0x1A, 0x1A));                  // drop; drop under unreachable
        ok(":i", "", Bin.c().b(0x00).b(0x1B));                       // select under unreachable
        ok(":i", "", Bin.c().b(0x02, 0x7F).b(0x00).end());           // block (result i32) unreachable end
        ok(":i", "", Bin.c().i32(1).b(0x04, 0x7F).b(0x00).b(0x05).i32(2).end()); // if/else with unreachable arm
        ok(":i", "", Bin.c().b(0x02, 0x7F).i32(5).br(0).end());      // br with value
        ok(":i", "", Bin.c().b(0x02, 0x7F).i32(5).i32(6).br(0).end()); // br discards extra operand below
        ok(":i", "", Bin.c().i32(1).i32(0).brTable(0, 0, 0).b(0x6A));    // br_table to function label with polymorphic tail
    }

    @Test
    void unreachableDoesNotHideTypeErrorsOfConcreteOperands() {
        // after unreachable the known i64 operand must still mismatch an i32 op
        bad(":i", "", Bin.c().b(0x00).i64(1).i32(1).b(0x6A), "type mismatch");
        // a polymorphic pop does not excuse a leftover concrete value at end
        bad(":", "", Bin.c().b(0x00).i32(1), "stack height mismatch");
        // after br, a concrete value of the wrong type for the block result still fails
        bad(":i", "", Bin.c().b(0x02, 0x7F).b(0x00).i64(1).end(), "type mismatch");
    }

    @Test
    void brTableArityMustAgree() {
        // label 0 = inner block (empty), default = function label (result i32): arity differs
        bad(":i", "", Bin.c().b(0x02, 0x40).i32(1).i32(0).brTable(1, 0).end().i32(1), "type mismatch");
        // matching arities pass
        ok(":i", "", Bin.c().b(0x02, 0x7F).i32(1).i32(0).brTable(0, 0, 0).end());
        // br_table index must be i32
        bad(":", "", Bin.c().b(0x02, 0x40).i64(0).brTable(0, 0).end(), "type mismatch");
    }

    @Test
    void localsOfBothTypesAndParamsAreVisible() {
        ok("il:l", "il", Bin.c().get(1).get(3).b(0x7C).set(3).get(2).b(0xAC).get(3).b(0x7C));
    }

    @Test
    void brIfKeepsLabelValueOnTheStack() {
        ok(":i", "", Bin.c().b(0x02, 0x7F).i32(7).i32(1).brIf(0).end());
        bad(":i", "", Bin.c().b(0x02, 0x7F).i32(1).brIf(0).end(), "stack underflow"); // the only i32 is consumed as the condition
    }
